import { useState } from 'react';
import type { FormEvent } from 'react';
import { Button, Combobox, Field, Input } from '@gener8v/ui';
import { COUNTRY_OPTIONS } from './countries';

export function App() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [country, setCountry] = useState<string | null>(null);
  const [submitted, setSubmitted] = useState(false);

  const countryMissing = submitted && !country;

  const onSubmit = (e: FormEvent) => {
    e.preventDefault();
    setSubmitted(true);
    if (!name.trim() || !country) return;
    // Hand off to the real save here.
  };

  return (
    <main className="container">
      <h1>New customer</h1>
      <form onSubmit={onSubmit} noValidate>
        <Field>
          <label className="field-label" htmlFor="customer-name">Name</label>
          <Input id="customer-name" value={name} onChange={(e) => setName(e.target.value)}
            invalid={submitted && !name.trim()} autoComplete="name" />
        </Field>
        <Field>
          <label className="field-label" htmlFor="customer-email">Email</label>
          <Input id="customer-email" type="email" value={email}
            onChange={(e) => setEmail(e.target.value)} autoComplete="email" />
        </Field>
        <Field>
          <Combobox
            id="customer-country"
            label="Country"
            placeholder="Start typing a country"
            options={COUNTRY_OPTIONS}
            value={country}
            onChange={setCountry}
            invalid={countryMissing}
            emptyMessage="No country matches"
          />
          {countryMissing && <p className="field-error" role="alert">Choose a country.</p>}
        </Field>
        <Button type="submit" variant="primary">Save</Button>
      </form>
    </main>
  );
}
